-- 只读验证；日期：2026-10-23。期望3个新草稿、3个可信能力消息、3个不可信输入及变量、零绑定。
SELECT id,prompt_definition_id,semantic_version,status,published_at FROM ai_prompt_version WHERE id IN ('30000000-0000-0000-0000-000000001009','30000000-0000-0000-0000-000000001010','30000000-0000-0000-0000-000000001014');
SELECT prompt_version_id,role,message_key,trusted_instruction,checksum=SHA2(content_template,256) AS message_checksum_valid FROM ai_prompt_message_template WHERE prompt_version_id IN ('30000000-0000-0000-0000-000000001009','30000000-0000-0000-0000-000000001010','30000000-0000-0000-0000-000000001014') ORDER BY prompt_version_id,ordinal;
SELECT COUNT(*) AS capability_count FROM ai_prompt_message_template WHERE prompt_version_id IN ('30000000-0000-0000-0000-000000001009','30000000-0000-0000-0000-000000001010','30000000-0000-0000-0000-000000001014') AND message_key='customer_service.evidence_scope.v1' AND role='SYSTEM' AND trusted_instruction=1;
SELECT COUNT(*) AS input_variable_count FROM ai_prompt_variable WHERE id IN ('50000000-0000-0000-0000-000000001009','50000000-0000-0000-0000-000000001010','50000000-0000-0000-0000-000000001014') AND variable_name='input_json' AND allow_untrusted_content=1;
SELECT COUNT(*) AS binding_count FROM ai_agent_version_prompt_binding WHERE prompt_version_id IN ('30000000-0000-0000-0000-000000001009','30000000-0000-0000-0000-000000001010','30000000-0000-0000-0000-000000001014');
SELECT v.id,v.checksum=SHA2(CONCAT('SYSTEM',CHAR(10),s.content_template,CHAR(10),'---',CHAR(10),'USER',CHAR(10),u.content_template),256) AS version_checksum_valid FROM ai_prompt_version v JOIN ai_prompt_message_template s ON s.prompt_version_id=v.id AND s.ordinal=1 JOIN ai_prompt_message_template u ON u.prompt_version_id=v.id AND u.ordinal=2 WHERE v.id IN ('30000000-0000-0000-0000-000000001009','30000000-0000-0000-0000-000000001010','30000000-0000-0000-0000-000000001014');
